begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','campaigns','campaign persistence exists');
select has_table('public','marketing_control','one durable automation control');
insert into public.organizations(id,name,slug) values('a3000000-0000-4000-8000-000000000001','Campaign fixture','campaign-030');
insert into auth.users(id) values('b3000000-0000-4000-8000-000000000001'),('b3000000-0000-4000-8000-000000000002');
insert into public.staff_profiles(user_id,organization_id,role) values('b3000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','manager'),('b3000000-0000-4000-8000-000000000002','a3000000-0000-4000-8000-000000000001','staff');
insert into public.business_settings(organization_id,revision,settings) values('a3000000-0000-4000-8000-000000000001',1,'{"brandName":"Fixture","brandVoice":"Plain","allowedTopics":["tech"],"forbiddenTopics":["banned"],"timezone":"Asia/Ho_Chi_Minh","goalSelection":"auto","managerGoal":"","timingMode":"constrained","dailyCap":1,"windows":[{"start":"09:00","end":"17:00"}],"objective":"mixed"}');
insert into public.products(id,organization_id,source_name,source_url,canonical_url,name,price_vnd,stock_quantity,in_stock,quality) values('c3000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','fixture','urn:campaign:fixture','urn:campaign:fixture','Fixture product',100000,2,true,'partial');
create function pg_temp.priority(rev integer default 0,req uuid default 'd3000000-0000-4000-8000-000000000001',cid uuid default 'e3000000-0000-4000-8000-000000000001',kind text default 'product',sid uuid default 'c3000000-0000-4000-8000-000000000001') returns jsonb language sql as $$select public.create_priority_campaign('a3000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001',cid,req,rev,jsonb_build_object('sourceKind',kind,'sourceId',sid,'objective','mixed'))$$;
select is(public.read_campaigns('a3000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000002')->'control'->>'status','PAUSED','initial default paused without enabling automation');
select throws_ok($$select public.create_priority_campaign('a3000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000002',gen_random_uuid(),gen_random_uuid(),0,'{}')$$,'42501','CAMPAIGN_FORBIDDEN','staff cannot create priority');
select lives_ok($$select pg_temp.priority()$$,'manager creates priority');
select lives_ok($$select pg_temp.priority()$$,'duplicate request replays');
select is((select count(*) from public.campaigns where organization_id='a3000000-0000-4000-8000-000000000001'),1::bigint,'duplicate creates one campaign');
select is((select priority_campaign_id from public.marketing_control where organization_id='a3000000-0000-4000-8000-000000000001'),'e3000000-0000-4000-8000-000000000001'::uuid,'priority persisted on control row');
select is((select scheduled_at from public.campaign_slots where campaign_id='e3000000-0000-4000-8000-000000000001'),null::timestamptz,'initial slot unscheduled');
select is((select content_version_id from public.campaign_slots where campaign_id='e3000000-0000-4000-8000-000000000001'),null::uuid,'no invented content version');
select is((select timezone from public.campaigns where id='e3000000-0000-4000-8000-000000000001'),'Asia/Ho_Chi_Minh','calendar timezone frozen from settings');
select throws_ok($$select pg_temp.priority(1,gen_random_uuid(),gen_random_uuid())$$,'40001','PRIORITY_IN_PROGRESS','second active priority rejected');
select is(public.read_campaigns('a3000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000002')->>'total','1','staff read-only list');
select lives_ok($$select public.finish_campaign('a3000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',1,'FAILED')$$,'trusted scoped terminal');
select lives_ok($$select public.finish_campaign('a3000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',1,'FAILED')$$,'terminal replay');
select is((select status from public.marketing_control where organization_id='a3000000-0000-4000-8000-000000000001'),'PAUSED','terminal never resumes');
select is((select priority_campaign_id from public.marketing_control where organization_id='a3000000-0000-4000-8000-000000000001'),null::uuid,'terminal clears only active ID');
select throws_ok($$select public.finish_campaign('a3000000-0000-4000-8000-000000000002','e3000000-0000-4000-8000-000000000001',gen_random_uuid(),2,'COMPLETED')$$,'42501','CAMPAIGN_FORBIDDEN','terminal rejects wrong organization');
select throws_ok($$update public.campaigns set source_snapshot='{}' where id='e3000000-0000-4000-8000-000000000001'$$,'55000','CAMPAIGN_IMMUTABLE','campaign facts immutable');
select ok(not has_table_privilege('service_role','public.campaign_slots','UPDATE'),'content/time refs not directly writable');
select ok(not has_function_privilege('authenticated','public.finish_campaign(uuid,uuid,uuid,integer,text)','EXECUTE'),'browser cannot finish campaigns');
insert into public.promotions(id,organization_id,label,scope,starts_at,expires_at) values('c3000000-0000-4000-8000-000000000002','a3000000-0000-4000-8000-000000000001','Expired','all',null,clock_timestamp()-interval '1 second');
select throws_ok($$select pg_temp.priority(2,gen_random_uuid(),gen_random_uuid(),'program','c3000000-0000-4000-8000-000000000002')$$,'22023','CAMPAIGN_SOURCE_INVALID','manual expired program rejected');
update public.products set stock_quantity=0 where id='c3000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.priority(2,gen_random_uuid(),gen_random_uuid())$$,'22023','CAMPAIGN_SOURCE_INVALID','zero stock blocked');
update public.products set stock_quantity=2 where id='c3000000-0000-4000-8000-000000000001';
create function pg_temp.reject_campaign_audit() returns trigger language plpgsql as $$begin raise exception 'campaign_audit_failure'; end$$;
create trigger campaign_audit_fixture before insert on public.audit_events for each row execute function pg_temp.reject_campaign_audit();
select throws_ok($$select pg_temp.priority(2,gen_random_uuid(),gen_random_uuid())$$,'P0001','campaign_audit_failure','audit failure rolls back priority');
select is((select revision from public.marketing_control where organization_id='a3000000-0000-4000-8000-000000000001'),2,'control revision rolled back');
select is((select count(*) from public.campaigns where organization_id='a3000000-0000-4000-8000-000000000001'),1::bigint,'campaign rollback');
drop trigger campaign_audit_fixture on public.audit_events;
update public.staff_profiles set active=false where user_id='b3000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.priority()$$,'42501','CAMPAIGN_FORBIDDEN','disabled manager cannot replay');
select ok(public.internal_campaign_program_matches('{"id":"c3000000-0000-4000-8000-000000000002","version":1,"title":"Offer","body":"Terms","active":true,"scope":"all","productIds":[],"startsAt":"2026-01-01T00:00:00Z","expiresAt":null,"discountType":"percent","discountValue":10}', '{"id":"c3000000-0000-4000-8000-000000000002","version":1,"title":"Offer","body":"Terms","scope":"all","productIds":[],"startsAt":"2026-01-01T00:00:00+00:00","expiresAt":null,"discountType":"percent","discountValue":10}'),'program timestamps compared as instants');
select ok(not public.internal_campaign_program_matches('{"version":1,"discountValue":10}', '{"version":1,"discountValue":20}'),'same version does not conceal changed program discount');
update public.staff_profiles set active=true where user_id='b3000000-0000-4000-8000-000000000001';
select lives_ok($$select public.create_priority_campaign('a3000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000003',gen_random_uuid(),2,'{"sourceKind":"product","sourceId":"C3000000-0000-4000-8000-000000000001","objective":"mixed"}')$$,'uppercase source UUID accepted');
select is((select source_ref from public.campaigns where id='e3000000-0000-4000-8000-000000000003'),'c3000000-0000-4000-8000-000000000001','source reference canonical for recent exclusion');
select * from finish();
rollback;
